CREATE TEMPORARY VIEW category_cluster_${grass_region_without_quote} AS
SELECT
    l1_category
    ,MAX(cluster) AS cluster
FROM
    mkplsearch_data_product.global_category_cluster_mapping
WHERE
    tree_type = 'global'
GROUP BY
    1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW kw_tag_${grass_region_without_quote} AS
SELECT
    country AS grass_region
    ,TRIM(LOWER(keyword)) AS keyword
    ,COLLECT_SET(tag_type) AS keyword_intention
FROM
    search_algo.search_keyword_tags_dump_latest
WHERE
    dt >= date_sub(${local_date}, 90)
    AND country = ${grass_region}
GROUP BY
    1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW item_cats_${grass_region_without_quote} AS
SELECT DISTINCT
    level1_global_be_category_id
    ,level1_global_be_category
    ,level2_global_be_category_id
    ,level2_global_be_category
    ,level3_global_be_category_id
    ,level3_global_be_category
    ,level4_global_be_category_id
    ,level4_global_be_category
    ,level5_global_be_category_id
    ,level5_global_be_category
FROM
    mp_item.dim_global_be_category__reg_s0_live
WHERE
    grass_date = ${local_date};

--sql_divide_splitter--

CREATE TEMPORARY VIEW all_cat_cnts_${grass_region_without_quote} AS
SELECT
    TRIM(LOWER(keyword)) AS keyword
    ,cat_id AS category_id
    ,level
    ,SUM(count) AS cat_cnt
FROM
    srdi_mart.dws_sr_data_warehouse_search_keyword_query_cat_count_1d
WHERE
    dt = ${local_date}
    AND operation = 'impression'
    AND country = ${grass_region}
    AND (
        (level IN (1,2) AND cat_id != 0)
        OR level IN (3,4,5)
    )
GROUP BY
    1,2,3;

--sql_divide_splitter--

CREATE TEMPORARY VIEW l1_cat_cnt_${grass_region_without_quote} AS
SELECT DISTINCT
    keyword
    ,l1.category_id AS cat_id_l1
    ,c.level1_global_be_category AS level1_global_be_category
    ,l1.cat_cnt AS cat_cnt_l1
FROM
    all_cat_cnts_${grass_region_without_quote} l1
LEFT JOIN
    item_cats_${grass_region_without_quote} c
ON
    l1.category_id = c.level1_global_be_category_id
WHERE
    l1.level = 1;

