CREATE TEMPORARY VIEW l1_restricted_${grass_region_without_quote} AS
SELECT
    keyword
    ,cat_id_l1
    ,level1_global_be_category
FROM (
    SELECT
        keyword
        ,cat_id_l1
        ,level1_global_be_category
        ,row_number() OVER(PARTITION BY keyword ORDER BY cat_cnt_l1 DESC) AS row_num
    FROM
        l1_cat_cnt_${grass_region_without_quote}
)
WHERE
    row_num = 1;

