        ,cat_id_l1
        ,level1_global_be_category
        ,cat_id_l2
        ,level2_global_be_category
        ,row_number() OVER(PARTITION BY keyword ORDER BY cat_cnt_l2 DESC) AS row_num
    FROM (
        SELECT
            l1r.keyword
            ,l1r.cat_id_l1
            ,l1r.level1_global_be_category
            ,l2.cat_id_l2
            ,l2.level2_global_be_category
