INSERT OVERWRITE TABLE ${schema}.dim_sr_data_warehouse_keyword_di
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
    a.keyword
    ,b.cluster
    ,a.level1_global_be_category
    ,a.level2_global_be_category
    ,a.level3_global_be_category
    ,a.level4_global_be_category
    ,a.level5_global_be_category
    ,a.cat_id_l1
    ,a.cat_id_l2
    ,a.cat_id_l3
    ,a.cat_id_l4
    ,a.cat_id_l5
    ,c.keyword_intention
    ,NULL
    ,NULL
    ,NULL
    ,NULL
    ,NULL
FROM
    l5_restricted_${grass_region_without_quote} a
LEFT JOIN
    category_cluster_${grass_region_without_quote} b
ON
    a.level1_global_be_category = b.l1_category
LEFT JOIN
    kw_tag_${grass_region_without_quote} c
ON
    a.keyword = c.keyword;
